describe('AI (cy.prompt) – generated commands', () => {
  it('signs in and creates a wish list', () => {
    // the real run used a fresh test account created in before(); these are placeholders
    const user = { email: 'ai-user@test.giftify', password: 'Password1' }

    // Prompt Step: visit /signin
    cy.visit('/signin')

    // Prompt Step: type {{email}} in the "Email or username" field
    cy.contains(/^\s*Email or username\s*$/).type(user.email)

    // Prompt Step: type {{password}} in the "Password" field
    cy.contains(/^\s*Password\s*$/).type(user.password)

    // Prompt Step: click the "Sign In" submit button inside the sign-in form card (not the link in the header)
    cy.get('#main form').contains(/^\s*Sign In\s*$/).click() // -> POST 200 /auth/signin

    // Prompt Step: verify the "My Lists" link is visible in the navigation bar
    cy.get('#root nav.container').contains(/^\s*My Lists\s*$/).should('be.visible')

    // Prompt Step: click the "My Lists" link in the navigation bar
    cy.get('#root nav.container').contains(/^\s*My Lists\s*$/).click() // -> /lists

    // Prompt Step: click the "+ New Wish List" button
    cy.contains(/^\s*\+ New Wish List\s*$/).click()

    // Prompt Step: type "Graduation party" in the "Title" field
    cy.contains(/^\s*Title\s*$/).type('Graduation party')

    // Prompt Step: select the option with value "graduation" in the "Occasion" dropdown
    cy.get('[name="occasion"]').select('graduation')

    // Prompt Step: click the "Create list" button in the dialog
    cy.get('#main div.modal').contains(/^\s*Create list\s*$/).click() // -> POST 201 /api/wishlists

    // Prompt Step: verify the page shows a wish list card containing "Graduation party"
    cy.get('[data-testid="wishlist-card"]').should('contain', 'Graduation party')

    cy.screenshot('06-ai-prompt-result')
  })
})
